//! Local browser diagnostics using the same extractor and matcher as the CLI.
//!
//! This module is also usable natively with the `web` feature, allowing public
//! sample reports to be generated by the identical implementation.

use std::io::Cursor;

use base64::{Engine, engine::general_purpose::STANDARD};
use image::{DynamicImage, ImageDecoder, ImageFormat, ImageReader, imageops::FilterType};
use magicextract::{CardExtractor, ExtractorConfig};
use serde::Serialize;
#[cfg(target_arch = "wasm32")]
use wasm_bindgen::prelude::*;

use crate::{CatalogIndex, Error, MatchOptions, Recognition, matching::VisualEvidence};

/// Maximum compressed photo bytes accepted by the browser engine.
const MAX_INPUT_BYTES: usize = 32 * 1024 * 1024;
/// Maximum dimension checked by the image decoder before pixel allocation.
const MAX_INPUT_DIMENSION: u32 = 8192;
/// Maximum decoded pixel count, preserving common 12-megapixel camera inputs.
const MAX_INPUT_PIXELS: u64 = 16_000_000;
/// Decoder allocation budget in addition to the strict dimension/pixel checks.
const MAX_DECODE_BYTES: u64 = 128 * 1024 * 1024;
/// Maximum long edge for an already-cropped diagnostic image.
const MAX_CROP_DIMENSION: u32 = 700;
/// Maximum combined embedded PNG data URLs in a diagnostic report.
const MAX_REPORT_IMAGE_BYTES: usize = 16 * 1024 * 1024;

/// One actual extracted crop and the evidence used to recognize it.
#[derive(Debug, Serialize)]
pub struct DiagnosticCard {
    /// Detected corners in oriented source-image pixels.
    pub corners: [[f32; 2]; 4],
    /// Area enclosed by the detection in source-image square pixels.
    pub area: f32,
    /// Unmodified recognition decisions from the portable matcher.
    pub recognition: Recognition,
    /// PNG data URL of the extractor output, oriented to its leading candidate.
    pub crop_data_url: String,
    /// PNG data URL of the extractor output before recognition orientation.
    pub raw_crop_data_url: String,
    /// Clockwise rotation applied to the crop for the leading candidate.
    ///
    /// This is a proposed orientation when recognition remains unknown.
    pub upright_rotation_degrees: u16,
    /// Actual components for the returned visual candidates, in ranking order.
    pub visual_evidence: Vec<VisualEvidence>,
}

/// Input geometry and complete diagnostics for the extracted card regions.
#[derive(Debug, Serialize)]
pub struct DiagnosticReport {
    /// Width after applying input EXIF orientation.
    pub width: u32,
    /// Height after applying input EXIF orientation.
    pub height: u32,
    /// Actual detected outlines, rectified images and recognition evidence.
    pub cards: Vec<DiagnosticCard>,
}

/// Reusable browser engine with a validated local reference index.
#[derive(Debug)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
pub struct BrowserEngine {
    /// Compact reference index held entirely in local memory.
    index: CatalogIndex,
    /// Higher-resolution extraction preserves small title and footer glyphs.
    extractor: CardExtractor,
}

#[cfg_attr(target_arch = "wasm32", wasm_bindgen)]
impl BrowserEngine {
    /// Load and validate a JSON index without making network requests.
    ///
    /// # Errors
    ///
    /// Returns an error string for an invalid index or extractor configuration.
    #[cfg_attr(target_arch = "wasm32", wasm_bindgen(constructor))]
    pub fn new(index_json: &str) -> Result<BrowserEngine, String> {
        let index =
            CatalogIndex::from_reader(index_json.as_bytes()).map_err(|error| error.to_string())?;
        let extractor = CardExtractor::new(ExtractorConfig {
            output_width: 500,
            output_height: 700,
            max_cards: 16,
            ..ExtractorConfig::default()
        })
        .map_err(|error| error.to_string())?;
        Ok(Self { index, extractor })
    }

    /// Decode a local photo and return JSON containing real extraction diagnostics.
    ///
    /// Set `cropped` when the input already contains one tightly cropped card;
    /// otherwise `magicextract` detects and perspective-corrects scene outlines.
    /// Input pixels and recognition stay in this process or browser tab.
    /// Inputs are limited to 32 MiB, 8192 pixels per edge and 16 megapixels.
    /// Scene diagnostics include at most 16 detections; already-cropped inputs
    /// are reduced to a 700-pixel long edge before matching and PNG encoding.
    ///
    /// # Errors
    ///
    /// Returns an error string for invalid image bytes, an unusable catalogue,
    /// extraction failure, recognition failure or JSON serialization failure.
    pub fn scan(&self, image_bytes: &[u8], cropped: bool) -> Result<String, String> {
        self.scan_report(image_bytes, cropped)
            .and_then(|report| serde_json::to_string(&report).map_err(Error::from))
            .map_err(|error| error.to_string())
    }

    /// Search enrolled metadata with independently supplied OCR observations.
    ///
    /// This returns a separate text ranking and does not alter visual confidence.
    ///
    /// # Errors
    ///
    /// Returns an error string for malformed observations or JSON serialization.
    pub fn text_search(&self, observations_json: &str) -> Result<String, String> {
        let observations =
            serde_json::from_str(observations_json).map_err(|error| error.to_string())?;
        let matches = crate::mtg::evidence::search(self.index.metadata(), &observations);
        serde_json::to_string(&matches).map_err(|error| error.to_string())
    }
}

impl BrowserEngine {
    /// Produce a structured diagnostic report using the browser implementation.
    ///
    /// # Errors
    ///
    /// Returns an error for invalid or oversized image bytes, failed extraction
    /// or recognition, PNG encoding failure, or embedded crops exceeding 16 MiB.
    pub fn scan_report(
        &self,
        image_bytes: &[u8],
        cropped: bool,
    ) -> Result<DiagnosticReport, Error> {
        let image = decode_input(image_bytes)?;
        let width = image.width();
        let height = image.height();
        let cards = if cropped {
            let bounded = if width.max(height) > MAX_CROP_DIMENSION {
                image.resize(MAX_CROP_DIMENSION, MAX_CROP_DIMENSION, FilterType::Triangle)
            } else {
                image.clone()
            };
            vec![self.diagnose(
                &DynamicImage::ImageRgb8(bounded.to_rgb8()),
                [
                    [0.0, 0.0],
                    [width as f32, 0.0],
                    [width as f32, height as f32],
                    [0.0, height as f32],
                ],
                width as f32 * height as f32,
            )?]
        } else {
            let mut cards = Vec::new();
            let mut image_bytes = 0_usize;
            for card in self.extractor.extract(&image)? {
                let diagnostic = self.diagnose(
                    &DynamicImage::ImageRgb8(card.image),
                    card.detection.corners.map(|point| [point.x, point.y]),
                    card.detection.area,
                )?;
                image_bytes = image_bytes
                    .saturating_add(diagnostic.crop_data_url.len())
                    .saturating_add(diagnostic.raw_crop_data_url.len());
                if image_bytes > MAX_REPORT_IMAGE_BYTES {
                    return Err(Error::InvalidInput(
                        "diagnostic crops exceed 16 MiB; scan fewer cards at once".into(),
                    ));
                }
                cards.push(diagnostic);
            }
            cards
        };
        Ok(DiagnosticReport {
            width,
            height,
            cards,
        })
    }

    /// Preserve an extractor crop and explain its unchanged visual ranking.
    ///
    /// # Errors
    ///
    /// Returns an error when recognition or PNG encoding fails.
    fn diagnose(
        &self,
        image: &DynamicImage,
        corners: [[f32; 2]; 4],
        area: f32,
    ) -> Result<DiagnosticCard, Error> {
        let (recognition, visual_evidence) = self
            .index
            .recognize_explained(image, &MatchOptions::default())?;
        let rotation = recognition
            .candidates
            .first()
            .map_or(0, |candidate| candidate.rotation_degrees);
        let raw_crop_data_url = data_url(image)?;
        let crop_data_url = match rotation {
            90 => data_url(&image.rotate90())?,
            180 => data_url(&image.rotate180())?,
            270 => data_url(&image.rotate270())?,
            _ => raw_crop_data_url.clone(),
        };
        Ok(DiagnosticCard {
            corners,
            area,
            recognition,
            crop_data_url,
            raw_crop_data_url,
            upright_rotation_degrees: rotation,
            visual_evidence,
        })
    }
}

/// Check photo dimensions before allocating decoded pixels, then honor EXIF.
///
/// # Errors
///
/// Returns an error for invalid image data or any configured photo resource limit.
fn decode_input(image_bytes: &[u8]) -> Result<DynamicImage, Error> {
    if image_bytes.len() > MAX_INPUT_BYTES {
        return Err(Error::InvalidInput(
            "photo exceeds 32 MiB; reduce its file size before scanning".into(),
        ));
    }
    let mut reader = ImageReader::new(Cursor::new(image_bytes)).with_guessed_format()?;
    let mut limits = image::Limits::default();
    limits.max_image_width = Some(MAX_INPUT_DIMENSION);
    limits.max_image_height = Some(MAX_INPUT_DIMENSION);
    limits.max_alloc = Some(MAX_DECODE_BYTES);
    reader.limits(limits);
    let mut decoder = reader.into_decoder()?;
    let (width, height) = decoder.dimensions();
    if u64::from(width) * u64::from(height) > MAX_INPUT_PIXELS {
        return Err(Error::InvalidInput(
            "photo exceeds 16 megapixels; resize it before scanning".into(),
        ));
    }
    let orientation = decoder.orientation()?;
    let mut image = DynamicImage::from_decoder(decoder)?;
    image.apply_orientation(orientation);
    Ok(image)
}

/// Encode a lossless crop for display without a server or external image upload.
///
/// # Errors
///
/// Returns an image encoding error if PNG generation fails.
fn data_url(image: &DynamicImage) -> Result<String, Error> {
    let mut bytes = Cursor::new(Vec::new());
    image.write_to(&mut bytes, ImageFormat::Png)?;
    Ok(format!(
        "data:image/png;base64,{}",
        STANDARD.encode(bytes.into_inner())
    ))
}

/// Exercise resource rejection before decoding and camera orientation in memory.
#[cfg(test)]
mod tests {
    use image::{Rgb, RgbImage};

    use super::*;

    /// Build a real JPEG with distinctive pixels for decoder-level tests.
    fn jpeg() -> Vec<u8> {
        let image = RgbImage::from_fn(32, 48, |x, y| Rgb([(x * 7) as u8, (y * 5) as u8, 85]));
        let mut bytes = Vec::new();
        image::codecs::jpeg::JpegEncoder::new_with_quality(&mut bytes, 95)
            .encode_image(&image)
            .unwrap();
        bytes
    }

    /// Malformed oversized headers fail before the decoder allocates image pixels.
    #[test]
    fn rejects_oversized_inputs_before_pixel_decode() {
        let mut image = jpeg();
        let start = image
            .windows(2)
            .position(|bytes| bytes == [0xff, 0xc0])
            .unwrap();
        image[start + 5..start + 7].copy_from_slice(&4097_u16.to_be_bytes());
        image[start + 7..start + 9].copy_from_slice(&4097_u16.to_be_bytes());
        assert!(
            matches!(decode_input(&image), Err(Error::InvalidInput(message)) if message.contains("megapixels"))
        );
        image[start + 7..start + 9].copy_from_slice(&8193_u16.to_be_bytes());
        assert!(decode_input(&image).is_err());
        assert!(
            matches!(decode_input(&vec![0; MAX_INPUT_BYTES + 1]), Err(Error::InvalidInput(message)) if message.contains("32 MiB"))
        );
    }

    /// Browser decoding rotates camera JPEGs before recording dimensions and outlines.
    #[test]
    fn applies_camera_orientation_before_geometry() {
        let original = jpeg();
        let raw = image::load_from_memory(&original).unwrap().to_rgb8();
        let exif = b"Exif\0\0II*\0\x08\0\0\0\x01\0\x12\x01\x03\0\x01\0\0\0\x06\0\0\0\0\0\0\0";
        let mut bytes = vec![0xff, 0xd8, 0xff, 0xe1];
        bytes.extend_from_slice(&((exif.len() + 2) as u16).to_be_bytes());
        bytes.extend_from_slice(exif);
        bytes.extend_from_slice(&original[2..]);
        let decoded = decode_input(&bytes).unwrap().to_rgb8();
        assert_eq!(decoded.dimensions(), (48, 32));
        assert_eq!(decoded, image::imageops::rotate90(&raw));
    }

    /// Large cropped cards retain source geometry while their PNG diagnostics stay bounded.
    #[test]
    fn bounds_cropped_diagnostics_without_changing_source_geometry() {
        let image = DynamicImage::ImageRgb8(RgbImage::from_fn(400, 800, |x, y| {
            Rgb([
                (x.wrapping_mul(31) ^ y) as u8,
                (y.wrapping_mul(17) ^ x) as u8,
                85,
            ])
        }));
        let mut index = CatalogIndex::new();
        index
            .add(
                crate::CardMetadata {
                    game: "mtg".into(),
                    id: "test".into(),
                    name: "Test".into(),
                    ..crate::CardMetadata::default()
                },
                &image,
            )
            .unwrap();
        let engine = BrowserEngine {
            index,
            extractor: CardExtractor::new(ExtractorConfig::default()).unwrap(),
        };
        let mut bytes = Cursor::new(Vec::new());
        image.write_to(&mut bytes, ImageFormat::Png).unwrap();
        let report = engine.scan_report(bytes.get_ref(), true).unwrap();
        assert_eq!((report.width, report.height), (400, 800));
        assert_eq!(report.cards[0].corners[2], [400.0, 800.0]);
        let raw = report.cards[0]
            .raw_crop_data_url
            .strip_prefix("data:image/png;base64,")
            .unwrap();
        let crop = image::load_from_memory(&STANDARD.decode(raw).unwrap()).unwrap();
        assert_eq!((crop.width(), crop.height()), (350, 700));
    }
}
